import table from "./coverage.json";
import type { Site } from "./types";

/**
 * How many of a site's questions the learner can use in their own language. A question is served in a language only when its wording
 * is translated (math bank templates, English bank wording, Korean bank meanings); the rest stays out of sight instead of showing text
 * the learner cannot read. The table is regenerated by `UPDATE_COVERAGE=1 npx vitest run tests/learn/coverage-table.test.ts` and checked
 * against the real content by that test.
 */
export type Coverage = { served: number; total: number };
export function coverageFor(site: Site, locale: string): Coverage | null {
  const row = (table as unknown as Record<string, Record<string, [number, number]>>)[site]?.[locale];
  return row ? { served: row[0], total: row[1] } : null;
}
/** the notice is shown only when part of the site is unavailable in the learner's language */
export const hasGap = (c: Coverage | null): c is Coverage => !!c && c.served < c.total;
